/// A before-and-after example for one rule: code it reports, and the same code fixed.
struct RuleExample: Sendable, Equatable {
    /// The language the example is written in, as its fence names it (`swift`, `typescript`, `php`, …).
    let language: String
    /// The code the rule reports.
    let before: String
    /// The same code, fixed.
    let after: String
}

/// The rule examples article (`RuleExamples.md`), available at runtime for the HTML report's example diffs.
///
/// The article's Markdown is embedded in the binary (`RuleExamplesText`, generated by
/// `Scripts/generate-rule-catalog.sh`) and parsed once, the first time an example is needed.
enum RuleExamples {
    /// Every example in the article, keyed by rule ID.
    private static let byRule: [String: RuleExample] = RuleExampleParser.examples(in: RuleExamplesText.markdown)

    /// Looks up a rule's example.
    ///
    /// - Parameter ruleID: The rule's ID, matched exactly.
    /// - Returns: The example, or `nil` if the article has none for the rule.
    static func example(for ruleID: String) -> RuleExample? {
        byRule[ruleID]
    }

    /// Every rule ID the article has an example for, sorted.
    static var ruleIDs: [String] {
        byRule.keys.sorted()
    }
}
